#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<long long> factorial(n + 1);
    factorial[0] = n;
    for (int i = 1; i < n; i++) {
        factorial[i] = (factorial[i - 1] * (n - i)) % m;
    }
    int size = n * (n - 1) + 1;
    vector<long long> dp(size, 0);
    int middle = (n * (n - 1)) / 2;
    vector<long long> temp(dp);
    dp[middle] = 1;
    long long answer = 0;
    for (int i = n - 1; i >= 0; i--) {
        int c = n - 1 - i;
        temp = dp;
        for (int j = 0; j < size; j++) {
            dp[j] = 0;
        }
        int limit = (c * (c - 1)) / 2;
        long long count = 0;
        for (int cur = -c; cur < 0; cur++) {
            int pairs = c + cur + 1;
            int start_j = middle - cur + 1;
            int end_j = middle + limit;
            for (int j = start_j; j <= end_j; j++) {
                if (j >= 0 && j < size) {
                    count = (count + temp[j] * pairs) % m;
                }
            }
        }
        long long mult = (i == 0) ? 1 : factorial[i - 1];
        answer = (answer + count * mult) % m;
        for (int j = middle - limit; j <= middle + limit; j++) {
            if (j >= 0 && j < size) {
                int c = n - 1 - i;
                for (int cur = -c; cur <= c; cur++) {
                    int idx = j + cur;
                    if (idx >= 0 && idx < size) {
                        int pairs = c - abs(cur) + 1;
                        dp[idx] = (dp[idx] + pairs * temp[j]) % m;
                    }
                }
            }
        }
    }
    cout << answer << "\n";
    return 0;
}
